def predecessor(name, raw):
    if name not in PINS: raise ValueError("unknown source name")
    pin=PINS[name]; digest=hashlib.sha256(raw).hexdigest()
    if digest==pin["before_sha256"]: return raw
    if digest!=pin["after_sha256"]: raise ValueError("unreviewed direct-card source")
    text=raw.decode("utf-8")
    for new,old in INVERSES[name]:
        if text.count(new)!=1: raise ValueError("exact inverse hunk differs")
        text=text.replace(new,old,1)
    result=text.encode("utf-8")
    if hashlib.sha256(result).hexdigest()!=pin["before_sha256"]: raise ValueError("complete predecessor differs")
    return result
def capture_predecessor(raw):
    return predecessor("ObservationCaptureEvidence.java", raw)
